bool solve(vector<vector<char>>& b) {
    for (int r = 0; r < 9; ++r)
      for (int c = 0; c < 9; ++c)
        if (b[r][c] == '.') {
          for (char d = '1'; d <= '9'; ++d)
            if (valid(b, r, c, d)) {
              b[r][c] = d;
              if (solve(b)) return true;
              b[r][c] = '.';          // backtrack
            }
          return false;                // no digit fits
        }
    return true;                       // board full
}

def solve(board):                       # 9x9 list of chars, '.' = empty
    def valid(r, c, ch):
        for i in range(9):
            if board[r][i] == ch or board[i][c] == ch:
                return False
            if board[3*(r//3) + i//3][3*(c//3) + i%3] == ch:
                return False
        return True

    def bt():
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for ch in "123456789":
                        if valid(r, c, ch):
                            board[r][c] = ch
                            if bt():
                                return True
                            board[r][c] = '.'      # backtrack
                    return False                   # no digit fits
        return True                                # board full
    bt()
    return board
